INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'sprueh', '{"nutzung":"sprueh"}'::jsonb, NULL, 'Sprühanwendung (Hochdruckreinigung, Gartensprenger und Autowäsche): Trübung < 10 NTU · pH 5 bis 9,5 · Rest-Chlor < 2,0 mg/l · Rest-Brom 0,0 mg/l', 0, '{"spalte":"Hochdruckreinigung, Gartensprenger und Autowäsche","truebung_max":10,"truebung_text":"< 10","ph_min":5,"ph_max":9.5,"ph_text":"5 bis 9,5","rest_chlor_max":2,"rest_chlor_text":"< 2,0","rest_brom_max":0,"rest_brom_text":"0,0","verfahren_truebung":"EN ISO 7027-1","verfahren_ph":"EN ISO 10523","verfahren_rest_chlor":"EN ISO 7393-2","verfahren_rest_brom":"EN ISO 10304-1"}'::jsonb, '\hline \multirow[t]{2}{*}{Parameter ${ }^{\text {a }}$} & Sprühanwendung & \multicolumn{3}{|l|}{Anwendung ohne Versprühen} & \multirow[t]{2}{*}{Prüfung} & \multirow[t]{2}{*}{System-Typ} \\
\hline & Hochdruckreinigung, Gartensprenger und Autowäsche & WCSpülung & Garten-bewässerung & Reinigung, d. h. Wasch-maschine & & \\
\hline Trübung (NTU) & < 10 & < 10 & N/A & < 10 & EN ISO 7027-1 & alle Systeme \\
\hline pH & 5 bis 9,5 & 5 bis 9,5 & 5 bis 9,5 & 5 bis 9,5 & EN ISO 10523 & alle Systeme \\
\hline Rest-Chlor (mg/l) & < 2,0 & < 2,0 & < 0,5 & < 2,0 & EN ISO 7393-2 & alle Systeme, wenn verwendet \\
\hline Rest-Brom (mg/l) & 0,0 & < 5,0 & 0,0 & < 5,0 & EN ISO 10304-1 & alle Systeme, wenn verwendet \\
\hline \multicolumn{7}{|c|}{a Zusätzlich zu diesen Parametern sollten alle Systeme auf Schwebstoffe und Färbung geprüft werden. Das behandelte Grauwasser sollte visuell klar, frei von aufschwimmenden Rückständen und für alle Verwendungszwecke farblich unbedenklich sein. Eine Färbung ist besonders für die Verwendung in der Waschmaschine relevant.} \\' FROM regulation_tables WHERE standard_code = 'DIN-EN-16941-2' AND edition = '2021' AND table_code = 'TABD2'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
