INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DIN-EN-16941-2', '2021', 'TABD3', 'Auswertung der bakteriologischen Überwachung — Statusbänder (Tabelle D.3)', 'Anhang D, Tab. D.3; §11', NULL, ARRAY['band']::text[], '[{"name":"ergebnis","type":"string"},{"name":"status","type":"string"},{"name":"status_text","type":"string"},{"name":"auswertung","type":"string"},{"name":"code","type":"number"}]'::jsonb, 'locked', 'Grauwassernutzungsanlagen müssen unbedingt in der Art geplant und installiert werden, dass das NichtTrinkwasser für den vorgesehenen Gebrauch taugt und keine Gefährdung der Gesundheit darstellt. Die Beispiele in Anhang D sind Mindestanforderungen. Strengere nationale oder im Rahmen der Planung festgelegte Vorgaben müssen vor den Werten in Anhang D Vorrang haben. — b Bei Abwesenheit von E. coli, intestinalen Enterokokken und Legionella, falls zutreffend, besteht keine Notwendigkeit, die Anlage außer Betrieb zu nehmen, wenn die gemessenen Werte von Coliformen den Richtwert um das 10fache überschreiten und eine erneute Probenahme zur Bestätigung der Ergebnisse durchgeführt wird.', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
