SELECT id, 'g_bis_10g', '{"band":"g_bis_10g"}'::jsonb, NULL, 'G bis 10 G → gelb: erneute Probenahme zur Bestätigung des Ergebnisses und Prüfen des Systembetriebs', 1, '{"ergebnis":"G bis 10 G","status":"gelb","status_text":"gelb","auswertung":"erneute Probenahme zur Bestätigung des Ergebnisses und Prüfen des Systembetriebs","code":2}'::jsonb, '\hline G bis 10 G & gelb & erneute Probenahme zur Bestätigung des Ergebnisses und Prüfen des Systembetriebs \\' FROM regulation_tables WHERE standard_code = 'DIN-EN-16941-2' AND edition = '2021' AND table_code = 'TABD3'
