INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'gt_10g', '{"band":"gt_10g"}'::jsonb, NULL, '>10 \mathrm{G} → rot: Nutzung des Grauwassers ausschließen, bis Problem gelöst ist', 2, '{"ergebnis":">10 \\mathrm{G}","status":"rot","status_text":"rot","auswertung":"Nutzung des Grauwassers ausschließen, bis Problem gelöst ist","code":3}'::jsonb, '\hline $>10 \mathrm{G}^{\mathrm{b}}$ & rot & Nutzung des Grauwassers ausschließen, bis Problem gelöst ist \\' FROM regulation_tables WHERE standard_code = 'DIN-EN-16941-2' AND edition = '2021' AND table_code = 'TABD3'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
