INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DIN-EN-16941-2', '2021', 'TABD4', 'Auswertung der Systemüberwachung — Statusbänder (Tabelle D.4)', 'Anhang D, Tab. D.4; §11', NULL, ARRAY['band']::text[], '[{"name":"ergebnis","type":"string"},{"name":"status","type":"string"},{"name":"status_text","type":"string"},{"name":"auswertung","type":"string"},{"name":"code","type":"number"}]'::jsonb, 'locked', 'Grauwassernutzungsanlagen müssen unbedingt in der Art geplant und installiert werden, dass das NichtTrinkwasser für den vorgesehenen Gebrauch taugt und keine Gefährdung der Gesundheit darstellt. Die Beispiele in Anhang D sind Mindestanforderungen. Strengere nationale oder im Rahmen der Planung festgelegte Vorgaben müssen vor den Werten in Anhang D Vorrang haben. — \hline \multicolumn{3}{|c|}{Bei der Überwachung des pH-Werts wird das System als unter Kontrolle angenommen (Status „grün“), wenn das Niveau innerhalb des in Tabelle D. 3 empfohlenen Bereichs liegt. Liegen die Werte außerhalb des Bereichs, erhält das System den Status „gelb“ und eine erneute Probenahme ist erforderlich. Treten Färbung oder abgesetzte Stoffe in störender Größe auf, ist es unerlässlich, die Funktion des Systems zu prüfen, um das Problem zu lösen.} \\', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
