VALUES ('DIN-EN-16941-2', '2021', 'ANHANGB', 'Arten von Grauwassernutzungsanlagen nach Art der Behandlung (Anhang B)', 'Anhang B; §5.1', NULL, ARRAY['anlagentyp']::text[], '[{"name":"bezeichnung","type":"string"},{"name":"beschreibung","type":"string"},{"name":"nutzungsbeschraenkung","type":"string"}]'::jsonb, 'anhaltswert', 'Grauwassernutzungsanlagen unterscheiden sich erheblich nach Komplexität und Größe und können nach der Art der Behandlung wie folgt klassifiziert werden:', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'direkt', '{"anlagentyp":"direkt"}'::jsonb, NULL, 'Anlagen für die direkte Nutzung (ohne Behandlung)', 0, '{"bezeichnung":"Anlagen für die direkte Nutzung (ohne Behandlung)","beschreibung":"Diese Anlagen verwenden einfache Geräte zur Sammlung von Grauwasser aus Einrichtungen und fördern es direkt zum Ort der Nutzung, ohne Behandlung und geringer oder keiner Speicherungsdauer, z. B. ein Grauwasser-Umstellventil.","nutzungsbeschraenkung":"Ist die Behandlung nicht Teil der Grauwassernutzugsanlage, sind Nutzungen auf unterirdische Bewässerung und Anwendungen ohne Versprühen beschränkt."}'::jsonb, 'a) Anlagen für die direkte Nutzung (ohne Behandlung)

Diese Anlagen verwenden einfache Geräte zur Sammlung von Grauwasser aus Einrichtungen und fördern es direkt zum Ort der Nutzung, ohne Behandlung und geringer oder keiner Speicherungsdauer, z. B. ein Grauwasser-Umstellventil.

Es ist möglich, Grauwasser ohne Behandlung zu nutzen, vorausgesetzt, dass eine längere Speicherung nicht erforderlich ist. Da die Qualität von unbehandeltem Grauwasser sich schnell verschlechtert, muss das gesammelte Grauwasser so schnell wie möglich genutzt werden.

Ist die Behandlung nicht Teil der Grauwassernutzugsanlage, sind Nutzungen auf unterirdische Bewässerung und Anwendungen ohne Versprühen beschränkt.' FROM regulation_tables WHERE standard_code = 'DIN-EN-16941-2' AND edition = '2021' AND table_code = 'ANHANGB'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'kurzzeit', '{"anlagentyp":"kurzzeit"}'::jsonb, NULL, 'Anlagen mit kurzzeitiger Rückhaltung', 1, '{"bezeichnung":"Anlagen mit kurzzeitiger Rückhaltung","beschreibung":"Diese Anlagen verwenden eine sehr einfache Behandlungstechnik, wie Abschöpfen von Fremdmaterial an der Oberfläche des gesammelten Grauwassers und Absetzen von Partikeln am Tankboden. Sie zielen darauf ab, Geruchsbildungen und Verschlechterungen der Wasserqualität zu vermeiden, indem sichergestellt wird, dass das behandelte Grauwasser nicht für eine längere Dauer gespeichert wird.","nutzungsbeschraenkung":null}'::jsonb, 'b) Anlagen mit kurzzeitiger Rückhaltung

Diese Anlagen verwenden eine sehr einfache Behandlungstechnik, wie Abschöpfen von Fremdmaterial an der Oberfläche des gesammelten Grauwassers und Absetzen von Partikeln am Tankboden. Sie zielen darauf ab, Geruchsbildungen und Verschlechterungen der Wasserqualität zu vermeiden, indem sichergestellt wird, dass das behandelte Grauwasser nicht für eine längere Dauer gespeichert wird.' FROM regulation_tables WHERE standard_code = 'DIN-EN-16941-2' AND edition = '2021' AND table_code = 'ANHANGB'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'physikalisch_chemisch', '{"anlagentyp":"physikalisch_chemisch"}'::jsonb, NULL, 'einfache physikalische/chemische Anlagen', 2, '{"bezeichnung":"einfache physikalische/chemische Anlagen","beschreibung":"Diese Anlagen verwenden Filter zur Entfernung von Fremdmaterial aus dem gesammelten Grauwasser vor der Speicherung, wobei generell chemische Desinfektionsmittel eingesetzt werden, um das Bakterienwachstum während der Speicherung zu stoppen.","nutzungsbeschraenkung":null}'::jsonb, 'c) einfache physikalische/chemische Anlagen

Diese Anlagen verwenden Filter zur Entfernung von Fremdmaterial aus dem gesammelten Grauwasser vor der Speicherung, wobei generell chemische Desinfektionsmittel eingesetzt werden, um das Bakterienwachstum während der Speicherung zu stoppen.' FROM regulation_tables WHERE standard_code = 'DIN-EN-16941-2' AND edition = '2021' AND table_code = 'ANHANGB'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'biologisch', '{"anlagentyp":"biologisch"}'::jsonb, NULL, 'biologische Anlagen', 3, '{"bezeichnung":"biologische Anlagen","beschreibung":"Diese Anlagen verwenden aerobe oder anaerobe Bakterien zur Beseitigung von unerwünschtem organischem Material im gesammelten Grauwasser. Im Falle aerober Behandlung können technische Einrichtungen oder Wasserpflanzen zur Belüftung des Wassers verwendet werden.","nutzungsbeschraenkung":null}'::jsonb, 'd) biologische Anlagen

Diese Anlagen verwenden aerobe oder anaerobe Bakterien zur Beseitigung von unerwünschtem organischem Material im gesammelten Grauwasser. Im Falle aerober Behandlung können technische Einrichtungen oder Wasserpflanzen zur Belüftung des Wassers verwendet werden.' FROM regulation_tables WHERE standard_code = 'DIN-EN-16941-2' AND edition = '2021' AND table_code = 'ANHANGB'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'biologisch_mechanisch', '{"anlagentyp":"biologisch_mechanisch"}'::jsonb, NULL, 'biologisch-mechanische Anlagen', 4, '{"bezeichnung":"biologisch-mechanische Anlagen","beschreibung":"Diese Anlagen verbinden biologische und mechanische Behandlung, z. B. Entfernung organischer Substanz durch mikrobielle Kulturen und Feststoffe durch Abtrennung. Durch Belüftung wird die bakterielle Aktivität unterstützt.","nutzungsbeschraenkung":null}'::jsonb, 'e) biologisch-mechanische Anlagen

Diese Anlagen verbinden biologische und mechanische Behandlung, z. B. Entfernung organischer Substanz durch mikrobielle Kulturen und Feststoffe durch Abtrennung. Durch Belüftung wird die bakterielle Aktivität unterstützt.' FROM regulation_tables WHERE standard_code = 'DIN-EN-16941-2' AND edition = '2021' AND table_code = 'ANHANGB'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
UPDATE regulation_tables SET verification_status = 'md_verified' WHERE standard_code = 'DIN-EN-16941-2' AND edition = '2021' AND table_code = 'ANHANGB' AND verification_status = 'imported_unverified';
COMMIT;
